                { children: '所有页面已统一到查询区、操作区、表格区和详情区的规范骨架。' },
              ]}
            />
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]}>
        <Col xs={24} lg={12}>
          <Card title="最近登录摘要" loading={summaryQuery.loading}>
            {summary?.recentLoginLogs?.length ? (
              <Timeline
